#include "stdlib/math/base/special/boxcoxinvf.h"
#include "stdlib/constants/float32/nan.h"
#include "stdlib/math/base/special/expf.h"
#include "stdlib/math/base/special/log1pf.h"
#include "stdlib/math/base/assert/is_nanf.h"

/**
* Computes the inverse of a one-parameter Box-Cox transformation for a single-precision floating-point number.
*
* @param y         input value
* @param lambda    power parameter
* @return          inverse of the Box-Cox transformation
*
* @example
* float v = stdlib_base_boxcoxinvf( 1.0f, 2.5f );
* // returns ~1.6505f
*/
float stdlib_base_boxcoxinvf( const float y, const float lambda ) {
	if ( stdlib_base_is_nanf( y ) || stdlib_base_is_nanf( lambda ) ) {
		return STDLIB_CONSTANT_FLOAT32_NAN;
	}
	if ( lambda == 0.0f ) {
		return stdlib_base_expf( y );
	}
	return stdlib_base_expf( stdlib_base_log1pf( lambda*y ) / lambda );
}
